function roman = toRoman(num)
    if num < 1 || num > 3999 || num ~= floor(num)
        error('Input must be an integer between 1 and 3999');
    end

    numerals = { ...
        1000, 'M'; ...
        900,  'CM'; ...
        500,  'D'; ...
        400,  'CD'; ...
        100,  'C'; ...
        90,   'XC'; ...
        50,   'L'; ...
        40,   'XL'; ...
        10,   'X'; ...
        9,    'IX'; ...
        5,    'V'; ...
        4,    'IV'; ...
        1,    'I' ...
    };

    roman = '';
    for i = 1:size(numerals, 1)
        value = numerals{i, 1};
        symbol = numerals{i, 2};
        while num >= value
            roman = [roman symbol]; %#ok<AGROW>
            num = num - value;
        end
    end
end
